// BLOCK 2 -- DATA CONTRACT
// One rule per field, matching your Data Contract sheet exactly.
const t = $input.item.json;

const VALID_CATEGORIES = ['HR', 'Device', 'IT Access', 'Systems', 'Facilities'];
const VALID_DEPARTMENTS = ['HR', 'Risk', 'Finance', 'Operations', 'Unassigned'];
const VALID_URGENCY = ['Low', 'Medium', 'High', 'Critical'];

// ticket_body -- required, non-empty, under 3000 chars.
// On fail: "Route to general queue, flag needs manual read"
let needsManualRead = false;
if (!t.ticket_body || t.ticket_body.trim().length === 0 || t.ticket_body.length >= 3000) {
  needsManualRead = true;
}

// ticket_category -- must match enum, else default to General + human triager.
const categoryPretagged = VALID_CATEGORIES.includes(t.ticket_category);
const ticket_category = categoryPretagged ? t.ticket_category : 'General';

// department -- default to Unassigned, flag for manual routing.
const department = VALID_DEPARTMENTS.includes(t.department) ? t.department : 'Unassigned';

// urgency -- default to Medium, flag for supervisor review.
const urgencyValid = VALID_URGENCY.includes(t.urgency);
const urgency = urgencyValid ? t.urgency : 'Medium';

// requester_employee_id -- required, must match an active employee record.
// TODO: replace this stub with a real HR/Workday lookup (HTTP Request node)
// before this goes anywhere near real traffic. For now we only check presence.
const requesterVerified = Boolean(t.requester_employee_id);

return [{
  json: {
    ...t,
    ticket_category,
    category_pretagged: categoryPretagged,
    // pre-tagged categories skip the LLM classifier and are trusted at full confidence
    classification_confidence: categoryPretagged ? 1.0 : null,
    department,
    urgency,
    needs_manual_read: needsManualRead,
    urgency_defaulted: !urgencyValid,
    requester_verified: requesterVerified,
  },
}];

// Data Contract failure: requester_employee_id missing / not verified.
// "Flag 'unverified requester', hold ticket until confirmed."
const t = $input.item.json;
return [{
  json: {
    ...t,
    final_outcome: 'held_unverified_requester',
    escalated: false,
    kb_similarity: null,
  },
}];

// BLOCK 1 -- TRIGGER, "what if it fires twice?"
// Dedupe on ticket_id + employee email, per your Trigger sheet.
//
// NOTE: getWorkflowStaticData persists small values on THIS workflow only,
// and is fine for a class demo. Before real traffic, swap this for a
// real "seen key" table (Redis / Postgres / a dedupe column in your DB).
const t = $input.item.json;
const dedupeKey = `${t.ticket_id}::${t.requester_employee_id}`;

const staticData = this.getWorkflowStaticData('global');
if (!staticData.seenKeys) staticData.seenKeys = {};

const isDuplicate = Boolean(staticData.seenKeys[dedupeKey]);
if (!isDuplicate) {
  staticData.seenKeys[dedupeKey] = Date.now();
}

return [{ json: { ...t, is_duplicate: isDuplicate } }];

// Duplicate delivery of an event we already processed. Drop it, but say so.
const t = $input.item.json;
return [{ json: { ...t, final_outcome: 'dropped_duplicate', escalated: false, kb_similarity: null } }];

