// BLOCK 3, Step 1 -- pull the classifier's JSON answer back out and
// re-attach it to the ORIGINAL ticket (the HTTP Request node above
// replaced $json with the OpenAI response, so we reach back to the
// last node that still had full ticket data).
const original = $('Validate Data Contract').item.json;
const raw = $input.item.json;

let parsed;
try {
  const content = raw.choices?.[0]?.message?.content ?? '{}';
  parsed = JSON.parse(content);
} catch (err) {
  parsed = { category: 'General', confidence: 0 };
}

return [{
  json: {
    ...original,
    ticket_category: parsed.category || 'General',
    classification_confidence: typeof parsed.confidence === 'number' ? parsed.confidence : 0,
  },
}];

// BLOCK 5 -- FAILURE MODE: classifier is not confident enough to trust.
// "Below 0.8 confidence, route to a human instead of auto-closing."
const t = $input.item.json;
return [{
  json: {
    ...t,
    final_outcome: 'flagged_for_human_triager_low_confidence',
    escalated: true,
    escalation_reason: `low_classifier_confidence=${t.classification_confidence}`,
    kb_similarity: null,
  },
}];

// BLOCK 3, Step 4 -- Escalate angry or at-risk employee.
// Sentiment/category/urgency are INPUTS. A human always makes the final call
// downstream (this node only flags that a human is needed; it does not act).
//
// TODO: replace the fake employee_tier read below once the ERM lookup HTTP
// node above is pointed at your real system and returns real tier data.
const original = $('Parse Classifier Response').item.json ?? $('Validate Data Contract').item.json;
const t = { ...original };

const ALWAYS_HUMAN_CATEGORIES = ['Security', 'Legal', 'HR']; // Failure Modes sheet, row 4
const sentimentScore = t.sentiment_score ?? 0; // wire up a real sentiment model/API here

const mustEscalate =
  ALWAYS_HUMAN_CATEGORIES.includes(t.ticket_category) ||
  t.urgency === 'Critical' ||
  sentimentScore <= -0.6;

return [{
  json: {
    ...t,
    sentiment_score: sentimentScore,
    escalated: mustEscalate,
    escalation_reason: mustEscalate
      ? `category=${t.ticket_category}, urgency=${t.urgency}, sentiment=${sentimentScore}`
      : null,
  },
}];

// Placeholder: your real KB search will return a similarity score.
// httpbin.org just echoes our request, so we fake a score here for
// testing. Delete this line once KB_MATCH points at your real KB search.
const t = $input.item.json;
const fakedSimilarity = 0.6; // <-- replace with real response.body.similarity
return [{ json: { ...t, kb_similarity: fakedSimilarity } }];

// BLOCK 6 -- OBSERVABILITY
// One row per run: run id, ticket id, every decision + confidence, final outcome.
const t = $input.item.json;

return [{
  json: {
    run_id: $execution.id,
    ticket_id: t.ticket_id,
    ticket_category: t.ticket_category,
    classification_confidence: t.classification_confidence ?? null,
    urgency: t.urgency,
    kb_similarity: t.kb_similarity ?? null,
    escalated: Boolean(t.escalated),
    escalation_reason: t.escalation_reason ?? null,
    final_outcome: t.final_outcome,
    timestamp: new Date().toISOString(),
  },
}];
